               a brick:Electric_Power_Sensor .
  ?occupancy_sensor brick:isPointOf ?zone ;
                    a brick:Occupancy_Sensor .
}

SELECT ?point ?ts_id WHERE {
  VALUES ?point { 
    <http://buildgraph.org/BG_large_office_2004_0000#Zone_F1_Z01.Occupancy_Sensor> 
    <http://buildgraph.org/BG_large_office_2004_0000#Zone_F1_Z01_Electric_Power_Sensor> 
